WITH combined_metrics AS (SELECT time, caller_service_name, service_name, system_type, span_kind, remote_addr, cnt, avg_duration, max_duration, min_duration, error_num, percent_duration FROM service_call_minute_entry WHERE caller_service_name in (${serviceName}) AND (system_type in ('mysql', 'redis', 'kafka', 'rocketmq') or span_kind = 2)
AND (time >= #{dateParam.startUTC}::TIMESTAMPTZ AND time < #{dateParam.endUTC}::TIMESTAMPTZ)
UNION ALL
SELECT time, caller_service_name, service_name, system_type, span_kind, remote_addr, cnt, avg_duration, max_duration, min_duration, error_num, percent_duration FROM service_call_minute_dependency WHERE caller_service_name in (${serviceName}) AND (system_type in ('mysql', 'redis', 'kafka', 'rocketmq') or span_kind = 2)
AND (time >= #{dateParam.startUTC}::TIMESTAMPTZ AND time < #{dateParam.endUTC}::TIMESTAMPTZ)
) SELECT caller_service_name, CASE WHEN system_type IN ('mysql', 'redis') THEN remote_addr ELSE service_name END AS service_name, system_type, SUM(cnt) AS cnt, AVG(avg_duration) AS avg_duration, MAX(max_duration) AS max_duration, MIN(min_duration) AS min_duration, SUM(error_num) AS error_num, approx_percentile(0.90, rollup(percent_duration)) AS p90_duration, approx_percentile(0.95, rollup(percent_duration)) AS p95_duration, approx_percentile(0.99, rollup(percent_duration)) AS p99_duration FROM combined_metrics GROUP BY caller_service_name, CASE WHEN system_type IN ('mysql', 'redis') THEN remote_addr ELSE service_name END, system_type;

WITH combined_metrics AS (SELECT time, caller_service_name, service_name, system_type, span_kind, cnt, avg_duration, max_duration, min_duration, error_num, percent_duration FROM service_call_minute_entry WHERE service_name in (${serviceName}) AND span_kind = 2
AND (time >= #{dateParam.startUTC}::TIMESTAMPTZ AND time < #{dateParam.endUTC}::TIMESTAMPTZ)
UNION ALL
SELECT time, caller_service_name, service_name, system_type, span_kind, cnt, avg_duration, max_duration, min_duration, error_num, percent_duration FROM service_call_minute_dependency WHERE service_name in (${serviceName}) AND span_kind = 2
AND (time >= #{dateParam.startUTC}::TIMESTAMPTZ AND time < #{dateParam.endUTC}::TIMESTAMPTZ)
) SELECT caller_service_name, service_name, system_type, SUM(cnt) AS cnt, AVG(avg_duration) AS avg_duration, MAX(max_duration) AS max_duration, MIN(min_duration) AS min_duration, SUM(error_num) AS error_num, approx_percentile(0.90, rollup(percent_duration)) AS p90_duration, approx_percentile(0.95, rollup(percent_duration)) AS p95_duration, approx_percentile(0.99, rollup(percent_duration)) AS p99_duration FROM combined_metrics GROUP BY caller_service_name, service_name, system_type;
